import { curvedDiagramPath, roundedDiagramPath } from './diagram_path'
import type { DiagramSelectHandler } from '../editing/diagram_selection'
import { DIAGRAM_DIMMED_OPACITY } from '../surface/diagram_emphasis_presentation'
